// Build 3-6 varied prompts from the approved draft (variation logic: composition,
// lighting, angle randomized per run — anti perceptual-hash).
const draft = $json;
const comps = ['close-up product hero shot', 'lifestyle context scene', 'flat-lay top-down', 'hands-on demonstration', 'minimal studio backdrop', 'dramatic side lighting'];
const n = 3 + Math.floor(Math.random() * 3);
const picked = comps.sort(() => Math.random() - 0.5).slice(0, n);
return picked.map((style, i) => ({ json: { idx: i, prompt: `${style} of ${draft.product_name || 'the product'}, vertical 9:16 composition, photorealistic, no text, no watermarks, no human faces`, video_id: draft.video_id } }));

// Extract base64 image -> binary for the assembly step. C2PA/SynthID metadata
// from Gemini is preserved by writing bytes verbatim (never re-encode here).
const part = $json.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
if (!part) { throw new Error('no image in response'); }
const idx = $('Build Varied Prompts').item.json.idx;
return [{ json: { idx, video_id: $('Build Varied Prompts').item.json.video_id }, binary: { data: { data: part.inlineData.data, mimeType: part.inlineData.mimeType || 'image/png', fileName: `still_${idx}.png` } } }];
